WITH enriched AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, NTILE(5) OVER (PARTITION BY level ORDER BY salary DESC, id ASC) AS salary_bucket, MIN(salary) OVER (PARTITION BY dept_id, level) AS dept_id_min_salary, NTILE(3) OVER (PARTITION BY job_title ORDER BY salary DESC, id ASC) AS salary_bucket_2, ROUND(salary / SUM(salary) OVER (PARTITION BY dept_id, manager_id), 4) AS salary_share, SUM(salary) OVER (ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary FROM employees) SELECT s.id, s.full_name, s.email, s.manager_id, s.job_title, s.salary, s.hire_date, s.is_remote, s.dept_id_min_salary, (SELECT AVG(e2.salary) FROM employees e2 WHERE e2.manager_id = s.manager_id) AS avg_employee_salary FROM enriched s ORDER BY hire_date DESC
